mapper.select:
select mn.*,
       bdd.Bdd_Name as bddName
from Con_Boq_Dtl mn
         left join Inv_Budget_Declare_Dtl bdd on mn.Boqd_Bdd_Id = bdd.Bdd_Id
         left join Con_Boq cb on cb.Boq_Id=mn.Boq_Id

    
        and cb.Te_Id = #{params.teId}
    
    
          mn.Boqd_Bdd_Id in
        
            #{bddId}
        
    
    
        and cb.Boq_State=#{params.boqState}
    


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.Boqd_Sort DESC

select mn.*, bdd.Bdd_Name as bddName from Con_Boq_Dtl mn left join Inv_Budget_Declare_Dtl bdd on mn.Boqd_Bdd_Id = bdd.Bdd_Id left join Con_Boq cb on cb.Boq_Id=mn.Boq_Id where mn.Boqd_Id in (select Boqd_Parent_Id from Con_Boq_Dtl where Boqd_Id in
#{id}
) order by mn.Boqd_Sort asc

select boqp.Boqd_Name as boqdParentName, (select ibdd.bdd_total from Inv_Budget_Declare_Dtl ibdd where ibdd.Bdd_Id=mn.Boqd_Bdd_Id) as bddTotal, mn.* from Con_Boq_Dtl mn left join Con_Boq boq on mn.Boq_Id = boq.Boq_Id left join Con_Boq_Dtl boqp on boqp.Boqd_Id=mn.Boqd_Parent_Id
boq.Boq_State=7
and mn.Boq_Id=#{boqId}
and mn.boqd_parent_id=#{parentId}
and boq.Con_Id=#{conId}
order by mn.Boqd_Sort asc
